import React, { useState, useCallback, useEffect } from 'react';
import useSchemaStore from '../store/schemaStore';

const Outputcontainer = ({ shouldDisplaySchemaOutput, shouldDisplaySqlOutput }) => {
  const { xmlOutput, mysqlOutput, jsonOutput, downloadXML, copyXML, downloadSQL, copySQL, downloadJSON, copyJSON } = useSchemaStore();
  const [copied, setCopied] = useState('');
  const [prism, setPrism] = useState(null);

  // Dynamically load Prism and required languages/styles only when outputs are present
  useEffect(() => {
    let mounted = true;
    const shouldLoad = (xmlOutput && xmlOutput.length) || (mysqlOutput && mysqlOutput.length) || (jsonOutput && jsonOutput.length);
    if (!shouldLoad) return;

    // load prism and some common language components + a theme
    Promise.all([
      import('prismjs'),
      import('prismjs/components/prism-markup'), // xml/html
      import('prismjs/components/prism-json'),
      import('prismjs/components/prism-sql'),
      import('prismjs/themes/prism.css'),
    ])
      .then(([PrismModule]) => {
        if (!mounted) return;
        setPrism(PrismModule);
      })
      .catch(() => {
        if (mounted) setPrism(null);
      });

    return () => { mounted = false; };
  }, [xmlOutput, mysqlOutput, jsonOutput]);

  const showCopied = useCallback((type) => {
    setCopied(type);
    setTimeout(() => setCopied(''), 1800);
  }, []);

  const handleCopyXML = async () => {
    try {
      const ok = await copyXML();
      if (ok) showCopied('xml');
    } catch (e) { }
  };

  const handleCopyJSON = async () => {
    try {
      const ok = await copyJSON();
      if (ok) showCopied('json');
    } catch (e) { }
  };

  const handleCopySQL = async () => {
    try {
      const ok = await copySQL();
      if (ok) showCopied('sql');
    } catch (e) { }
  };

  return (
      <div className="output-container">
        {shouldDisplaySchemaOutput && (
          <div className="output-section">
            <h3>
              <b>db_schema.xml</b>
            </h3>
            {prism ? (
              <pre className="language-markup"><code dangerouslySetInnerHTML={{ __html: prism.highlight(xmlOutput || '', prism.languages.markup, 'markup') }} /></pre>
            ) : (
              <pre style={{whiteSpace: 'pre-wrap'}}>{xmlOutput}</pre>
            )}
            <button
              className="btn btn-secondary mr-2"
              onClick={downloadXML}
            >
              Download
            </button>
            <button className="btn btn-secondary" onClick={handleCopyXML}>
              Copy Schema
            </button>
            {copied === 'xml' && <span className="text-success" style={{ marginLeft: 8, fontWeight: 600 }}>Copied!</span>}
          </div>
        )}
        <div className="output-sub-container">
          {shouldDisplaySchemaOutput && (
            <div className="output-section">
              <h3>
                <b>db_schema_whitelist.json</b>
              </h3>
              {prism ? (
                <pre className="language-json"><code dangerouslySetInnerHTML={{ __html: prism.highlight(jsonOutput || '', prism.languages.json, 'json') }} /></pre>
              ) : (
                <pre style={{whiteSpace: 'pre-wrap'}}>{jsonOutput}</pre>
              )}
              <button
                className="btn btn-secondary mr-2"
                onClick={downloadJSON}
              >
                Download
              </button>
              <button className="btn btn-secondary" onClick={handleCopyJSON}>
                Copy JSON
              </button>
              {copied === 'json' && <span className="text-success" style={{ marginLeft: 8, fontWeight: 600 }}>Copied!</span>}
            </div>
          )}

          {shouldDisplaySqlOutput && (
            <div className="output-section">
              <h3>
                <b>MySQL Query</b>
              </h3>
              {prism ? (
                // Prism has no dedicated SQL highlighter component by default in all builds, but we loaded prism-sql
                <pre className="language-sql"><code dangerouslySetInnerHTML={{ __html: prism.highlight(mysqlOutput || '', prism.languages.sql, 'sql') }} /></pre>
              ) : (
                <pre style={{whiteSpace: 'pre-wrap'}}>{mysqlOutput}</pre>
              )}
              <button
                className="btn btn-secondary mr-2"
                onClick={downloadSQL}
              >Download</button>
              <button className="btn btn-secondary" onClick={handleCopySQL}>
                Copy Query
              </button>
              {copied === 'sql' && <span className="text-success" style={{ marginLeft: 8, fontWeight: 600 }}>Copied!</span>}
            </div>
          )}
        </div>
      </div>
  );
};

export default Outputcontainer;